def rows(matrix):
    return [[int(matrix[i, j]) for j in range(matrix.ncols())] for i in range(matrix.nrows())]


def row_hnf(generators):
    matrix = fmpz_mat(generators).hnf()
    return fmpz_mat([row for row in rows(matrix) if any(row)])


def integral_matrix(matrix, description):
    result = []
    for i in range(matrix.nrows()):
        row = []
        for j in range(matrix.ncols()):
            value = matrix[i, j]
            if value.denominator != 1:
                raise ValueError(description)
            row.append(int(value.numerator))
        result.append(row)
    return fmpz_mat(result)


def identity(n, scalar=1):
    return fmpz_mat([[scalar * int(i == j) for j in range(n)] for i in range(n)])


def _lattice_checks(basis, products, shifted_rows, standard_gram, w):
    n = basis.ncols()
    if type(w) is not int or w <= 0:
        raise ValueError("known relative norm must be a positive integer scalar")
    if basis.nrows() != n or not basis.det():
        raise ValueError("full-rank square integral ideal basis required")
    action = integral_matrix(fmpz_mat(shifted_rows) * basis.inv(),
                             "lattice is not closed under the public ring generator")
    product_hnf = row_hnf(products)
    if product_hnf != identity(n, w):
        raise ValueError("polarization identity I*bar(I)=w*A failed")
    raw_gram = basis * standard_gram * basis.transpose()
    gram = []
    for row in rows(raw_gram):
        if any(value % w for value in row):
            raise ValueError("normalized trace form is not integral")
        gram.append([value // w for value in row])
    gram = fmpz_mat(gram)
    if any(fmpz_mat([row[:k] for row in rows(gram)[:k]]).det() <= 0 for k in range(1, n + 1)):
        raise ValueError("normalized trace form is not positive definite")
    if action * gram * action.transpose() != gram:
        raise ValueError("public ring action is not an isometry")
    return {"ideal_basis_rows": rows(basis), "ideal_index": str(abs(int(basis.det()))),
            "polarized_product_hnf": rows(product_hnf), "normalized_gram": rows(gram),
            "normalized_gram_determinant": str(int(gram.det())),
            "ring_generator_action_rows": rows(action),
            "basis_max_coefficient_bits": max(abs(x).bit_length() for row in rows(basis) for x in row),
            "input_conditions_verified": True,
            "input_conditions_alone_prove_a_normalized_generator_exists": False}


def cm_input_certificate(field, basis, w):
    """Check actual ideal products, module action and positive trace form.

    Only odd prime cyclotomic orders are supported by this reference; the
    imported theorem is more general. A valid certificate is NOT a solver.
    """
    if not isprime(field.d) or field.d < 3:
        raise ValueError("this reduction is restricted to odd prime conductors")
    n = field.degree
    if basis.ncols() != n:
        raise ValueError("ideal basis dimension does not match the order")
    values = rows(basis)
    # Tr(zeta^i * bar(zeta^j)) = ell*delta_ij - 1.
    standard = fmpz_mat([[field.d * int(i == j) - 1 for j in range(n)] for i in range(n)])
    products = [field.multiply(a, field.conjugate(b)) for a in values for b in values]
    result = _lattice_checks(basis, products,
                            [field.multiply(a, field.root(1)) for a in values], standard, w)
    if (fmpz_mat(result["ring_generator_action_rows"]) ** field.d != identity(n)
            or int(result["normalized_gram_determinant"]) != field.d ** (field.d - 2)):
        raise ValueError("cyclotomic action or discriminant check failed")
    result["order_rank"] = n
    result["known_relative_norm_coefficients"] = list(field.constant(w))
    return result


def order_description(field):
    n = field.degree
    return {"conductor": field.d, "rank": n, "basis": "1,zeta,...,zeta^(ell-2)",
            "multiplication_table": [[list(field.root(i + j)) for j in range(n)] for i in range(n)],
            "conjugation_basis_images": [list(field.root(-i)) for i in range(n)],
            "CM_order_reason": "Z[zeta_ell] is the maximal order of a cyclotomic CM field",
            "trace_gram": [[field.d * int(i == j) - 1 for j in range(n)] for i in range(n)]}


def _cyclic_product(a, b):
    n = len(a)
    return tuple(sum(a[i] * b[(j - i) % n] for i in range(n)) for j in range(n))


def _reverse(a):
    return tuple(a[-i % len(a)] for i in range(len(a)))


def group_ring_input_certificate(source, abc):
    """R=Z[X]/(X^ell-1): add augmentation divisibility by p to public carries."""
    p, ell = source.p, source.d
    if not isprime(ell):
        raise ValueError("group-ring lift here requires an odd prime conductor")
    basis = rows(identity(ell))
    constraints = [(source.teichmuller_root(t, e), p ** e)
                   for t, e in valuation_profile(abc, ell) if e]
    constraints.append((1, p))
    for root, modulus in constraints:
        evaluations = [sum(c * pow(root, j, modulus) for j, c in enumerate(row)) % modulus for row in basis]
        pivot = next((i for i, value in enumerate(evaluations) if value % p), None)
        if pivot is None:
            raise ValueError("split-prime kernel lost surjectivity")
        pivot_row = basis[pivot][:]
        inverse = pow(evaluations[pivot], -1, modulus)
        for i in range(ell):
            if i != pivot:
                multiplier = evaluations[i] * inverse % modulus
                basis[i] = [x - multiplier * y for x, y in zip(basis[i], pivot_row)]
        basis[pivot] = [modulus * x for x in pivot_row]
    basis = row_hnf(basis)
    values = rows(basis)
    products = [_cyclic_product(a, _reverse(b)) for a in values for b in values]
    result = _lattice_checks(basis, products, [row[-1:] + row[:-1] for row in values], identity(ell), p * p)
    shift = fmpz_mat(result["ring_generator_action_rows"])
    if (abs(int(basis.det())) != p ** ell or int(result["normalized_gram_determinant"]) != 1
            or shift ** ell != identity(ell) or (-shift) ** ell != identity(ell, -1)):
        raise ValueError("group-ring index, unimodularity or signed action failed")
    result.update({"ring": "Z[X]/(X^ell-1)", "augmentation_divisible_by_p": True,
                   "known_autocorrelation": [p * p] + [0] * (ell - 1),
                   "signed_group_generator": "-cyclic_shift; order 2*ell; its ell-th power is -I",
                   "external_reference": "1501.00178v3, Remark 8.6 and Theorem 1.1",
                   "generator_recovery_executed": False})
    return result


def group_ring_witness(source, generator):
    """CALIBRATION ONLY: lift an already known normalized cyclotomic generator.

    The public group-ring input above never calls this function. Augmentation
    p fixes sign; primary normalization fixes the cyclic/root ambiguity.
    """
    field, p, ell = source.field, source.p, source.d
    primary = primary_normalize(field, generator, p)
    if (p - sum(primary)) % ell:
        raise ValueError("primary representative cannot have augmentation p")
    c = (p - sum(primary)) // ell
    lifted = tuple(x + c for x in primary) + (c,)
    if _cyclic_product(lifted, _reverse(lifted)) != (p * p,) + (0,) * (ell - 1):
        raise ValueError("lifted generator has incorrect autocorrelation")
    return {"coefficients": list(lifted), "augmentation": sum(lifted),
            "autocorrelation": list(_cyclic_product(lifted, _reverse(lifted))),
            "cyclotomic_projection": list(field.reduce(lifted)),
            "uses_an_already_known_generator_not_an_input_constructor": True}


def public_reduction(source, abc):
    """Polynomial-size explicit input to two published classical theorems."""
    basis, index = public_ideal_basis(source, abc)
    basis = row_hnf(rows(basis))
    cm = cm_input_certificate(source.field, basis, source.p * source.p)
    if int(cm["ideal_index"]) != index:
        raise ValueError("HNF changed the public carry ideal")
    return {"p": source.p, "conductor": source.d, "residue_root": source.root,
            "triple": list(abc), "positive_embedding_carries": [list(x) for x in valuation_profile(abc, source.d)],
            "CM_theorem_input": cm, "group_ring_theorem_input": group_ring_input_certificate(source, abc),
            "YES_premise": "Jacobi ideal and relative-norm identities supply J, not just I*bar(I)=p^2*A",
            "exact_root_selection": "prime-conductor J=1 mod(1-zeta)^2; existing primary_normalize",
            "used_true_sum_or_LLL_or_phase": False,
            "classical_known_norm_recovery_executed": False,
            "local_reduction_independently_or_formally_reviewed": False}


def run_controls():
    small = []
    orders = {}
    for p, ell in ((7, 3), (13, 3), (11, 5), (131, 5), (29, 7), (379, 7)):
        source = ReferenceCharacters(p, ell)
        abc = (1, 1, 2) if ell == 3 else (1, 1, 1)
        record = public_reduction(source, abc)
        assert source._indices is None
        orders[str(ell)] = order_description(source.field)
        # This separately charged truth calibration is not used by either reduction.
        known = source.triple(abc)
        record["native_witness_calibration"] = group_ring_witness(source, known)
        record["native_character_table_entries_charged"] = len(source.indices)
        small.append(record)
    source = ReferenceCharacters(2 ** 61 - 1, 11, residue_root=54008984094220448)
    orders["11"] = order_description(source.field)
    multiplicities = Counter(tuple(sorted(abc)) for abc in itertools.product(range(1, 11), repeat=3) if sum(abc) % 11)
    representatives = {}
    for abc in multiplicities:
        representatives.setdefault(valuation_profile(abc, 11), abc)
    large = [public_reduction(source, abc) for abc in representatives.values()]
    assert source._indices is None and not source.reference_summands
    return {"schema_version": "jacobi-known-norm-classical-reduction-v1",
            "source_sha256": hashlib.sha256(Path(__file__).read_bytes()).hexdigest(),
            "surface_dependency_sha256": hashlib.sha256(
                (PACKAGE / "jacobi_surface_reconstruction.py").read_bytes()).hexdigest(),
            "external_theorem": THEOREM, "orders": orders, "small_controls": small,
            "large_public_controls": large, "large_distinct_ideal_profiles": len(large),
            "large_character_table_entries_or_reference_summands": 0,
            "decision": "Prime-conductor proposal loses its claimed asymptotic quantum opening under the stated Jacobi identities and published theorem",
            "scope": "Exact split Fermat surfaces at odd prime conductor with public split root, polynomial in conductor and log p",
            "not_claimed": ["Gentry-Szydlo implementation", "uniform LLL success", "generic classical PIP",
                            "composite-conductor root identification", "all CM point counts", "refutation of an external paper"],
            "accepted_speedup_candidate": False, "new_central_negative_registered": False,
            "independent_or_formal_review_completed": False}


def main():
    parser = argparse.ArgumentParser(description=__doc__)
